package main

import (
	"fmt"
	"sync"
)

func square(i int, nums, results []int, wg *sync.WaitGroup) {
	defer wg.Done()
	results[i] = nums[i] * nums[i]
}

func main() {
	var nums []int
	for {
		var n int
		if _, err := fmt.Scan(&n); err != nil {
			break
		}
		nums = append(nums, n)
	}

	results := make([]int, len(nums))
	var wg sync.WaitGroup
	for i := range nums {
		wg.Add(1)
		go square(i, nums, results, &wg)
	}
	wg.Wait()
	fmt.Println(results)
}

