import (
	"fmt"
	"sync"
)

const NumChunks = 4

func main() {
	nums := make([]int, 100)
	for i := range nums {
		nums[i] = i + 1
	}

	size := len(nums) / NumChunks
	partial := make([]int, NumChunks)
	var wg sync.WaitGroup
	for c := 0; c < NumChunks; c++ {
		lo, hi := c*size, (c+1)*size
		wg.Add(1)
		go func(c int, part []int) {
			defer wg.Done()
			sum := 0
			for _, v := range part {
				sum += v
			}
			partial[c] = sum
		}(c, nums[lo:hi])
	}
	wg.Wait()

	total := 0
	for _, p := range partial {
		total += p
	}
	fmt.Println(partial)
	fmt.Println("Total:", total)
}

