package main

import (
	"fmt"
	"sync"
)

const NumChunks = 3

func main() {
	nums := []int{7, 42, 3, 19, 88, 5, 61, 27, 14, 73, 9, 50}

	size := len(nums) / NumChunks
	partial := make([]int, NumChunks)
	var wg sync.WaitGroup
	for c := 0; c < NumChunks; c++ {
		lo, hi := c*size, (c+1)*size
		wg.Add(1)
		go func(c int, part []int) {
			defer wg.Done()
			m := part[0]
			for _, v := range part[1:] {
				if v > m {
					m = v
				}
			}
			partial[c] = m
		}(c, nums[lo:hi])
	}
	wg.Wait()

	best := partial[0]
	for _, p := range partial[1:] {
		if p > best {
			best = p
		}
	}
	fmt.Println(partial)
	fmt.Println("Max:", best)
}

