package main

import (
	"fmt"
	"sort"
	"sync"
)

type SafeCounter struct {
	mu     sync.Mutex
	counts map[string]int
}

func (c *SafeCounter) Inc(word string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.counts[word]++
}

func main() {
	words := []string{"go", "rust", "go", "zig", "rust", "go"}
	counter := SafeCounter{counts: make(map[string]int)}
	var wg sync.WaitGroup
	for _, w := range words {
		wg.Add(1)
		go func(w string) {
			defer wg.Done()
			counter.Inc(w)
		}(w)
	}
	wg.Wait()

	keys := make([]string, 0, len(counter.counts))
	for k := range counter.counts {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		fmt.Printf("%s: %d\n", k, counter.counts[k])
	}
}
